// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address oracleAddr) public {
        // Ensure we are dealing with a contract address to match the expected usage
        vm.assume(oracleAddr != address(0));
        vm.assume(oracleAddr.code.length > 0);

        // Deploy a minimal helper that implements IOracleProvider to satisfy the internal requirement
        MinimalOracle oracle = new MinimalOracle();

        // We need to initialize the contract to set up the oracle
        // For simplicity, we can directly store the oracle address using the internal _oracle slot
        // However, we must use the public initializer. Since initialize can only be called once in the actual contract,
        // we'll call it with a minimal valid payload.
        // But the initializer checks for IController, so we need a minimal controller.
        // Alternatively, we can use vm.store to set the oracle slot directly, but vm.store is REJECTED.
        // So we must deploy a minimal IController to pass the initializer.
        MinimalController controller = new MinimalController();
        MinimalPayoffDefinition payoffDef = new MinimalPayoffDefinition();

        // We cannot easily call initialize without a full setup, but we can use the cheatcode to store values if allowed?
        // The rules say NO vm.store. So we must construct a proper initialization path.
        // Let's create a minimal product info and call initialize through the controller.
        // The initialize modifier checks initializer(1) and msg.sender must be a controller.
        // We can prank as the controller.

        IProduct.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TEST";
        info.oracle = IOracleProvider(address(oracle));
        info.payoffDefinition = PayoffDefinitionLib.PayoffDefinition(PayoffDefinitionLib.PayoffType.PASS_THROUGH, PayoffDefinitionLib.PayoffDirection.LONG, bytes30(0));
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = JumpRateUtilizationCurve(PackedFixed18.wrap(0), PackedFixed18.wrap(0), PackedFixed18.wrap(0), PackedUFixed18.wrap(0));

        vm.startPrank(address(controller));
        c.initialize(info);
        vm.stopPrank();

        // Now call oracle()
        IOracleProvider returned = c.oracle();

        // The property: the returned address must be a contract (code.length > 0).
        // The buggy version returns zero bytes, which corresponds to address(0) or some default, not a contract.
        assertTrue(address(returned).code.length > 0);
    }
}

// Minimal IOracleProvider implementation for initialization
contract MinimalOracle is IOracleProvider {
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function atVersion(uint256) external view returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function sync() external returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
}

// Minimal IController to pass initialization
contract MinimalController is IController {
    ICollateral public override collateral;
    IIncentivizer public override incentivizer;
    IBeacon public override productBeacon;
    IMultiInvoker public override multiInvoker;
    UFixed18 public override protocolFee;
    UFixed18 public override minFundingFee;
    UFixed18 public override liquidationFee;
    UFixed18 public override incentivizationFee;
    UFixed18 public override minCollateral;
    uint256 public override programsPerProduct;
    address public override pauser;
    bool public override paused;

    mapping(uint256 => Coordinator) public override coordinators;
    mapping(IProduct => uint256) public override coordinatorFor;

    function isProduct(IProduct product) external view returns (bool) {
        return address(product) != address(0);
    }

    function owner() external view returns (address) { return address(this); }
    function owner(uint256) external view returns (address) { return address(this); }
    function owner(IProduct) external view returns (address) { return address(this); }
    function treasury() external view returns (address) { return address(this); }
    function treasury(uint256) external view returns (address) { return address(this); }
    function treasury(IProduct) external view returns (address) { return address(this); }

    // Unused but required by interface
    function initialize(ICollateral, IIncentivizer, IBeacon) external {}
    function createCoordinator() external returns (uint256) { return 0; }
    function updateCoordinatorPendingOwner(uint256, address) external {}
    function acceptCoordinatorOwner(uint256) external {}
    function updateCoordinatorTreasury(uint256, address) external {}
    function createProduct(uint256, IProduct.ProductInfo calldata) external returns (IProduct) { return IProduct(address(0)); }
    function updateCollateral(ICollateral) external {}
    function updateIncentivizer(IIncentivizer) external {}
    function updateProductBeacon(IBeacon) external {}
    function updateMultiInvoker(IMultiInvoker) external {}
    function updateProtocolFee(UFixed18) external {}
    function updateMinFundingFee(UFixed18) external {}
    function updateLiquidationFee(UFixed18) external {}
    function updateIncentivizationFee(UFixed18) external {}
    function updateMinCollateral(UFixed18) external {}
    function updateProgramsPerProduct(uint256) external {}
    function updatePauser(address) external {}
    function updatePaused(bool) external {}
}

// Minimal PayoffDefinitionLib for creating a valid definition
library PayoffDefinitionLib {
    enum PayoffType { PASS_THROUGH }
    enum PayoffDirection { LONG }
}

contract MinimalPayoffDefinition {
    function valid() external pure returns (bool) { return true; }
    function transform(Fixed18 price) external pure returns (Fixed18) { return price; }
}

