pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 rawPrice, uint8 payoffType, uint8 payoffDirection, address oracleAddr) public {
        // Bound payoffType to valid enum values and ensure oracle is a contract with code
        vm.assume(payoffType <= 2);
        vm.assume(payoffDirection <= 2);
        vm.assume(oracleAddr.code.length > 0);
        vm.assume(rawPrice > 0 && rawPrice < type(int256).max / 1e18);

        // Build product info using valid fuzzed parameters
        IProduct.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "T";
        info.payoffDefinition = PayoffDefinition(
            PayoffDefinitionLib.PayoffType(payoffType),
            PayoffDefinitionLib.PayoffDirection(payoffDirection),
            bytes30(0)
        );
        info.oracle = IOracleProvider(oracleAddr);
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(0.01e18);
        info.makerFee = UFixed18.wrap(0.01e18);
        info.takerFee = UFixed18.wrap(0.01e18);
        info.positionFee = UFixed18.wrap(0.01e18);
        info.makerLimit = UFixed18.wrap(100000e18);
        info.utilizationCurve = JumpRateUtilizationCurve(
            PackedFixed18.wrap(int128(0.05e18)),
            PackedFixed18.wrap(int128(1e18)),
            PackedFixed18.wrap(int128(0.1e18)),
            PackedUFixed18.wrap(uint128(0.8e18))
        );

        // Initialize the product
        vm.prank(address(this));
        c.initialize(info);

        // Call oracle() and assert the returned address is a contract with code
        address returnedOracle = address(c.oracle());
        assertTrue(returnedOracle.code.length > 0);
    }
}

