pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";
import {IOracleProvider} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(uint256 oracleVersion, int256 price) public {
        // deploy a minimal valid IOracleProvider to use in initialization
        MockOracle oracle = new MockOracle();
        oracle.setVersion(oracleVersion, price);

        IProduct.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TST";
        info.oracle = IOracleProvider(address(oracle));
        info.payoffDefinition = PayoffDefinition(PayoffDefinitionLib.PayoffType.NONE, PayoffDefinitionLib.PayoffDirection.NONE, bytes30(0));
        // remaining fields with safe defaults
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(type(uint256).max);
        info.utilizationCurve = JumpRateUtilizationCurve(PackedFixed18.wrap(0), PackedFixed18.wrap(1e18), PackedFixed18.wrap(1e18), PackedUFixed18.wrap(1e18));

        // Initialize C with the oracle
        vm.prank(address(new MockController(address(c)))); // minimal controller that allows product creation
        c.initialize(info);

        // After initialization, oracle() must return an address with code
        address ret = address(c.oracle());
        uint256 size;
        assembly { size := extcodesize(ret) }
        assertTrue(size > 0);
    }
}

contract MockOracle is IOracleProvider {
    uint256 public currentVersionId;
    int256 public currentPrice;

    function setVersion(uint256 version, int256 price) external {
        currentVersionId = version;
        currentPrice = price;
    }

    function sync() external returns (OracleVersion memory) {
        return OracleVersion(currentVersionId, block.timestamp, Fixed18.wrap(currentPrice));
    }
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion(currentVersionId, block.timestamp, Fixed18.wrap(currentPrice));
    }
    function atVersion(uint256) external view returns (OracleVersion memory) {
        return OracleVersion(currentVersionId, block.timestamp, Fixed18.wrap(currentPrice));
    }
}

