    address public product;
    constructor(address _product) { product = _product; }
    function isProduct(IProduct) external view returns (bool) { return true; }
    function coordinatorFor(IProduct) external view returns (uint256) { return 0; }
    function owner(uint256) external view returns (address) { return address(this); }
    function incentivizer() external view returns (address) { return address(0); }
    function collateral() external view returns (address) { return address(0); }
    function pauser() external view returns (address) { return address(0); }
    function paused() external view returns (bool) { return false; }
    function multiInvoker() external view returns (address) { return address(0); }
    function minFundingFee() external view returns (UFixed18) { return UFixed18.wrap(0); }
}

