// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    struct PayoffDefinition {
        uint8 payoffType;
        uint8 payoffDirection;
        bytes30 data;
    }

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(
        string calldata name,
        string calldata symbol,
        address oracle,
        uint8 payoffType,
        uint8 payoffDirection,
        bytes30 data,
        uint64 maintenance,
        uint64 fundingFee,
        uint64 makerFee,
        uint64 takerFee,
        uint64 positionFee,
        uint64 makerLimit,
        int128 minRate,
        int128 maxRate,
        int128 targetRate,
        uint128 targetUtilization
    ) public {
        vm.assume(oracle.code.length > 0);

        // Build ProductInfo that will be passed to initialize
        // Ensure payoff type is valid (PASSTHROUGH = 0 or TRANSFORM = 1 or PASSTHROUGH_LIKE = 2)
        vm.assume(payoffType <= 2);
        // Ensure payoff direction is valid (LONG = 0 or SHORT = 1)
        vm.assume(payoffDirection <= 1);

        // Create oracle interface mock
        // We need oracle to be a contract that implements IOracleProvider
        // The fuzzer provides an address, but it must have code. We deploy a minimal oracle.
        MockOracle mockOracle = new MockOracle();

        IProduct.ProductInfo memory info = IProduct.ProductInfo(
            name,
            symbol,
            PayoffDefinitionLib.PayoffDefinition(PayoffDefinitionLib.PayoffType(payoffType), PayoffDefinitionLib.PayoffDirection(payoffDirection), data),
            IOracleProvider(address(mockOracle)),
            UFixed18.wrap(uint256(maintenance) * 1e18),
            UFixed18.wrap(uint256(fundingFee) * 1e18),
            UFixed18.wrap(uint256(makerFee) * 1e18),
            UFixed18.wrap(uint256(takerFee) * 1e18),
            UFixed18.wrap(uint256(positionFee) * 1e18),
            UFixed18.wrap(uint256(makerLimit) * 1e18),
            JumpRateUtilizationCurve(
                PackedFixed18.wrap(minRate),
                PackedFixed18.wrap(maxRate),
                PackedFixed18.wrap(targetRate),
                PackedUFixed18.wrap(targetUtilization)
            )
        );

        // Initialize the contract
        vm.prank(address(this));
        c.initialize(info);

        // Get the stored payoff definition
        IProduct.PayoffDefinition memory storedPayoff = c.payoffDefinition();

        // The reference should return the same definition that was stored;
        // The mutant returns an empty definition (0, 0, bytes30(0)), which differs when the stored definition is not empty.
        // Assert that the returned payoff definition matches what was passed in (the stored definition).
        assertTrue(
            storedPayoff.payoffType == PayoffDefinitionLib.PayoffType(payoffType) &&
            storedPayoff.payoffDirection == PayoffDefinitionLib.PayoffDirection(payoffDirection) &&
            bytes32(storedPayoff.data) == bytes32(data)
        );
    }
}

contract MockOracle {
    function sync() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }

    function currentVersion() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }

    function atVersion(uint256) external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(
        string memory name,
        string memory symbol,
        bytes30 payoffData
    ) public {
        // Build an admissible PayoffDefinition; use PASSTHROUGH / LONG to keep it simple
        PayoffDefinition memory pd = PayoffDefinition(
            PayoffDefinitionLib.PayoffType.PASSTHROUGH,
            PayoffDefinitionLib.PayoffDirection.LONG,
            payoffData
        );

        // Build Oracle mock – consistent with UPayoffProvider initialization (must be a contract)
        // Use a minimal placeholder that implements IOracleProvider (here we mock it simply).
        // However IOracleProvider is an interface; deploying a real oracle is complex, but we only need
        // an address that is a contract. We deploy an empty contract which implements IOracleProvider.
        // Actually any contract address works as long as Address.isContract() returns true.
        // We deploy a simple contract for that purpose.
        DummyOracle oracle = new DummyOracle();

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: name,
            symbol: symbol,
            payoffDefinition: pd,
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(0.05e18),
            fundingFee: UFixed18.wrap(0.01e18),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0.001e18),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(1000e18),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: Fixed18.wrap(0.10e18),
                maxRate: Fixed18.wrap(1.00e18),
                targetRate: Fixed18.wrap(0.30e18),
                targetUtilization: UFixed18.wrap(0.80e18)
            })
        });

        // Initialize C. Only contracts can call initializer (UInitializable requires msg.sender is controller).
        // Assume the test contract acts as the controller (deployer).
        // UPayoffProvider initialization calls _updateOracle which calls Address.isContract on oracle, so oracle must have code.
        vm.prank(address(this));
        c.initialize(info);

        // After initialization, retrieve payoffDefinition and compare to passed pd.
        PayoffDefinition memory stored = c.payoffDefinition();

        bool payoffTypeMatch = (stored.payoffType == pd.payoffType);
        bool payoffDirectionMatch = (stored.payoffDirection == pd.payoffDirection);
        bool payoffDataMatch = (PayoffDefinition.unwrap(stored) == PayoffDefinition.unwrap(pd));

        // Universal property: payoffDefinition() must return exactly the initialized PayoffDefinition.
        // The mutant returns a hardcoded empty one, so this will fail for some fuzzed pd.
        assertTrue(payoffTypeMatch && payoffDirectionMatch && payoffDataMatch);
    }
}

contract DummyOracle is IOracleProvider {
    function sync() external returns (OracleVersion memory) {}
    function currentVersion() external view returns (OracleVersion memory) {}
    function atVersion(uint256) external view returns (OracleVersion memory) {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes30 data, uint8 payoffTypeInt, uint8 payoffDirectionInt) public {
        vm.assume(payoffTypeInt <= uint8(type(PayoffDefinitionLib.PayoffType).max));
        vm.assume(payoffDirectionInt <= uint8(type(PayoffDefinitionLib.PayoffDirection).max));

        PayoffDefinitionLib.PayoffType payoffType = PayoffDefinitionLib.PayoffType(payoffTypeInt);
        PayoffDefinitionLib.PayoffDirection payoffDirection = PayoffDefinitionLib.PayoffDirection(payoffDirectionInt);
        PayoffDefinition memory pd = PayoffDefinition(payoffType, payoffDirection, data);

        IProduct.ProductInfo memory productInfo = IProduct.ProductInfo({
            name: "Test",
            symbol: "TST",
            payoffDefinition: pd,
            oracle: IOracleProvider(address(this)),
            maintenance: UFixed18.wrap(1e18),
            fundingFee: UFixed18.wrap(1e18),
            makerFee: UFixed18.wrap(0.5e18),
            takerFee: UFixed18.wrap(0.5e18),
            positionFee: UFixed18.wrap(0.1e18),
            makerLimit: UFixed18.wrap(1000e18),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(int128(0)),
                maxRate: PackedFixed18.wrap(int128(0)),
                targetRate: PackedFixed18.wrap(int128(0)),
                targetUtilization: PackedUFixed18.wrap(uint128(0))
            })
        });

        vm.prank(msg.sender);
        c.initialize(productInfo);

        PayoffDefinition memory stored = c.payoffDefinition();
        bytes32 orig = keccak256(abi.encode(pd));
        bytes32 ret = keccak256(abi.encode(stored));

        assertTrue(orig == ret);
    }
}

contract IOracleProvider {
    function sync() external returns (OracleVersion memory) {}
    function currentVersion() external view returns (OracleVersion memory) {}
    function atVersion(uint256) external view returns (OracleVersion memory) {}
}

struct OracleVersion {
    uint256 version;
    uint256 timestamp;
    Fixed18 price;
}

library PayoffDefinitionLib {
    enum PayoffType { PASSTHROUGH, CALL, PUT }
    enum PayoffDirection { LONG, SHORT }
}

struct PayoffDefinition {
    PayoffDefinitionLib.PayoffType payoffType;
    PayoffDefinitionLib.PayoffDirection payoffDirection;
    bytes30 data;
}

typedef Fixed18 is int256;
typedef UFixed18 is uint256;
typedef PackedFixed18 is int128;
typedef PackedUFixed18 is uint128;

struct JumpRateUtilizationCurve {
    PackedFixed18 minRate;
    PackedFixed18 maxRate;
    PackedFixed18 targetRate;
    PackedUFixed18 targetUtilization;
}

interface IController {
