interface IMultiInvoker {}

interface IBeacon {}

interface IBatcher {}

interface IEmptySetReserve {}

struct Accumulator {
    Fixed18 maker;
    Fixed18 taker;
}

struct Position {
    UFixed18 maker;
    UFixed18 taker;
}

struct PrePosition {
    uint256 oracleVersion;
    Position openPosition;
