}

library Math {
    function max(uint256 a, uint256 b) internal pure returns (uint256) { return a > b ? a : b; }
    function min(uint256 a, uint256 b) internal pure returns (uint256) { return a < b ? a : b; }
}

library Fixed18Lib {
    int256 constant BASE = 1e18;
    function from(int256 a) internal pure returns (Fixed18) { return Fixed18.wrap(a * BASE); }
    function from(UFixed18 a) internal pure returns (Fixed18) { return Fixed18.wrap(int256(UFixed18.unwrap(a))); }
    function from(int256 s, UFixed18 m) internal pure returns (Fixed18) { return from(m); }
    function div(Fixed18 a, Fixed18 b) internal pure returns (Fixed18) { return Fixed18.wrap(Fixed18.unwrap(a) * BASE / Fixed18.unwrap(b)); }
}

library UFixed18Lib {
    uint256 constant BASE = 1e18;
    uint256 constant ONE = BASE;
    function max(UFixed18 a, UFixed18 b) internal pure returns (UFixed18) { return a > b ? a : b; }
    function sub(UFixed18 a, UFixed18 b) internal pure returns (UFixed18) { return UFixed18.wrap(UFixed18.unwrap(a) - UFixed18.unwrap(b)); }
}

library JumpRateUtilizationCurveLib {
    function compute(JumpRateUtilizationCurve memory curve, UFixed18) internal pure returns (Fixed18) { return Fixed18.wrap(0); }
}

library PositionLib {
