pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes memory name, bytes memory symbol) public {
        // Build a ProductInfo with a valid payoff definition that is not the default
        IProduct.ProductInfo memory info;
        info.name = string(name);
        info.symbol = string(symbol);
        info.oracle = IOracleProvider(address(0x1)); // dummy, will fail if actually called, but only payoffDefinition matters
        info.payoffDefinition = PayoffDefinition(PayoffDefinitionLib.PayoffType.PASSTHROUGH, PayoffDefinitionLib.PayoffDirection.SHORT, bytes30(uint240(1)));
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = JumpRateUtilizationCurve(PackedFixed18.wrap(0), PackedFixed18.wrap(0), PackedFixed18.wrap(0), PackedUFixed18.wrap(0));

        // Adversarial oracle that is a contract (to pass isContract check) but would revert if used
        MockOracle oracle = new MockOracle();
        info.oracle = IOracleProvider(address(oracle));

        // Expect revert during initialization because the oracle's currentVersion will revert, so we cannot fully init.
        // Instead, we must deploy a working oracle or avoid initialization that calls it.
        // However, the test must drive c through payoffDefinition. Since c cannot be initialized without a valid oracle,
        // we craft a minimal oracle that works.
        vm.expectRevert();
        c.initialize(info);
        // The above will revert, but that's fine because we only need to compare payoffDefinition before/after.
        // The property is about return value after storage, but if we cannot store, we directly observe mutant vs reference.
        // Actually, the reference file defines payoffDefinition() as reading from private storage;
        // the mutant always returns default. We can compare the return value to the stored one after initialization.
        // Since we cannot initialize without a working oracle and other dependencies,
        // we observe that after a successful init, the two differ.
        // Let's make a fully working oracle and contract to allow init.

        // Create a brand new C and a working oracle
        c = new C();
        WorkingOracle wo = new WorkingOracle();
        IProduct.ProductInfo memory info2 = info;
        info2.oracle = IOracleProvider(address(wo));
        info2.payoffDefinition = PayoffDefinition(PayoffDefinitionLib.PayoffType.PASSTHROUGH, PayoffDefinitionLib.PayoffDirection.SHORT, bytes30(uint240(42)));
        info2.maintenance = UFixed18.wrap(0);
        info2.fundingFee = UFixed18.wrap(0);
        info2.makerFee = UFixed18.wrap(0);
        info2.takerFee = UFixed18.wrap(0);
        info2.positionFee = UFixed18.wrap(0);
        info2.makerLimit = UFixed18.wrap(0);
        info2.utilizationCurve = JumpRateUtilizationCurve(PackedFixed18.wrap(0), PackedFixed18.wrap(0), PackedFixed18.wrap(0), PackedUFixed18.wrap(0));
        // We also need a controller that is a contract and fulfills collateral/incentivizer etc. Minimal:
        address controllerAddr = address(new MinimalController());
        vm.prank(controllerAddr);
        c.initialize(info2);

        // Now c is initialized. payoffDefinition() should return info2.payoffDefinition.
        PayoffDefinition memory returned = c.payoffDefinition();
        PayoffDefinition memory expected = info2.payoffDefinition;

        // The universal property: returned definition matches the one passed during initialization.
        assertTrue(
            returned.payoffType == expected.payoffType &&
            returned.payoffDirection == expected.payoffDirection &&
            returned.data == expected.data
        );
    }
}

