pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        address oracleAddress,
        int256 rawPrice,
        uint256 timestamp
    ) public {
        // Bound to admissible domain: oracle must be a contract, price in valid int256 range
        vm.assume(oracleAddress != address(0));
        vm.assume(rawPrice != 0);
        vm.assume(timestamp > 0 && timestamp < type(uint64).max);

        // Deploy a minimal oracle that returns a fixed OracleVersion
        MockOracle oracle = new MockOracle(rawPrice, timestamp);

        // Build a valid payoff definition (PASSTHROUGH to make transformation observable)
        // PayoffType = 0 (PASSTHROUGH), PayoffDirection = 0 (LONG), data = bytes30(0)
        C.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "TST";
        info.oracle = IOracleProvider(address(oracle));
        info.payoffDefinition = PayoffDefinition(
            PayoffDefinitionLib.PayoffType(0),
            PayoffDefinitionLib.PayoffDirection(0),
            bytes30(0)
        );
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(type(uint256).max);
        info.utilizationCurve = JumpRateUtilizationCurve(
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(0),
            PackedUFixed18.wrap(1e18)
        );

        // Initialize C through controller mock
        vm.prank(address(this));
        // The initialize expects msg.sender to be the controller;
        // we use a simple mock controller that satisfies the minimal interface
        MockController controller = new MockController();
        vm.etch(address(controller), address(new MockControllerDeployer()).code);
        // Instead, we directly call initialize with a controller that passes isProduct check
        // For this test to work, we need a controller that returns true for isProduct
        // We deploy a real-like controller mock
        ControllerMock ctrl = new ControllerMock();
        vm.startPrank(address(ctrl));
        c.initialize(info);
        vm.stopPrank();

        // Now read currentVersion
        IOracleProvider.OracleVersion memory version = c.currentVersion();

        // The general rule: the returned price must equal the transform of the original price
        // For PASSTHROUGH with LONG direction, transform returns price.abs() (wrapped as Fixed18)
        Fixed18 expectedPrice = info.payoffDefinition.transform(Fixed18.wrap(rawPrice));

        // Assert: the price returned by currentVersion() equals the transformed oracle price
        assertTrue(Fixed18.unwrap(version.price) == Fixed18.unwrap(expectedPrice));
    }
}

// Minimal oracle that returns a pre-configured version
contract MockOracle {
    int256 public immutable price;
