        bytes memory payoffDefBytes = new bytes(32);
        assembly {
            mstore(add(payoffDefBytes, 32), or(shl(248, payoffType), or(shl(240, payoffDirection), 0)))
        }
        PayoffDefinition memory pd;
        assembly {
            pd := mload(add(payoffDefBytes, 32))
        }

        // Initialize the product with this oracle and payoff definition
        IProduct.ProductInfo memory info;
        info.oracle = IOracleProvider(address(oracle));
        info.payoffDefinition = pd;
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = JumpRateUtilizationCurve(PackedFixed18.wrap(0), PackedFixed18.wrap(0), PackedFixed18.wrap(0), PackedUFixed18.wrap(0));
        info.name = "test";
        info.symbol = "TST";

        // We need to be the controller for initialization
        vm.mockCall(
            address(c),
            abi.encodeWithSelector(IController.isProduct.selector),
            abi.encode(true)
        );
        c.initialize(info);

        // Get the oracle's raw current version price
        IOracleProvider.OracleVersion memory rawVersion = oracle.currentVersion();
        Fixed18 rawPrice = rawVersion.price;

        // Get the product's currentVersion price
        IOracleProvider.OracleVersion memory productVersion = c.currentVersion();
        Fixed18 productPrice = productVersion.price;

        // The rule: product price must equal payoffDefinition.transform applied to raw price
        // Since the payoff definition might be invalid for some fuzzed inputs, we only check when valid
        // For a valid payoff definition, transform should be applied.
        // We use try/catch on the transform to handle invalid definitions gracefully
        try this.tryTransform(pd, rawPrice) returns (Fixed18 transformed) {
            // If transform succeeds, the product price must equal the transformed price
            assertTrue(Fixed18.unwrap(productPrice) == Fixed18.unwrap(transformed));
        } catch {
            // If transform fails (invalid payoff definition), the initialization would have reverted,
            // so we can't test here. Skip by assuming false? Actually the initialize would have reverted.
            // So we assume the initialization succeeded, meaning the payoff definition is valid.
            // But since we already called initialize above and it didn't revert (because of mock),
            // we need to handle the case where the definition is invalid.
            // We'll just skip by not asserting anything in the catch block.
        }
    }

    // Helper to try transform and catch errors
    function tryTransform(PayoffDefinition memory pd, Fixed18 price) external pure returns (Fixed18) {
        return pd.transform(price);
    }
}

contract Oracle {
    int256 private _price;
    uint256 private _timestamp = block.timestamp;
    uint256 private _version = 1;

    function setPrice(int256 price) external {
