contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 rawPrice) public {
        // Bound to a plausible non-zero price to avoid trivial zero case and avoid overflow in transform
        rawPrice = bound(rawPrice, 1, 1e24);
        // Deploy a minimal oracle that returns the fuzzed price
        SimpleOracle oracle = new SimpleOracle(int256(rawPrice));
        // Use a simple passthrough payoff definition that transforms price (e.g., x2)
        bytes memory data = abi.encode(int256(2e18)); // multiplier = 2 in 18-decimal fixed point
        PayoffDefinition memory payoffDef = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.PASSTHROUGH,
            payoffDirection: PayoffDefinitionLib.PayoffDirection.LONG,
            data: bytes30(bytes32(data) >> 16)
        });
        // Initialize the product with minimal valid parameters (oracle, payoff, zero fees, etc.)
        IProduct.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "TST";
        info.oracle = IOracleProvider(address(oracle));
        info.payoffDefinition = payoffDef;
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(type(uint256).max);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(100e18),
            targetRate: PackedFixed18.wrap(10e18),
            targetUtilization: PackedUFixed18.wrap(0.8e18)
        });
        c.initialize(info);

        // Get the transformed price from reference logic: payoffDefinition.transform(rawPrice)
        Fixed18 expectedPrice = payoffDef.transform(Fixed18.wrap(int256(rawPrice)));

        // Call currentVersion and compare
        IOracleProvider.OracleVersion memory version = c.currentVersion();
        Fixed18 actualPrice = version.price;

        // Assert: actual transformed price equals expected transformed price
        assertTrue(Fixed18.unwrap(actualPrice) == Fixed18.unwrap(expectedPrice));
    }
}

