pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oraclePrice) public {
        // Use a payoff definition that transforms the price (e.g., multiplies by 2)
        // The reference contract should return the transformed price; the mutant returns raw oracle price.

        // Deploy a mock oracle that returns the fuzzed price
        MockOracle oracle = new MockOracle();
        oracle.setPrice(oraclePrice);

        // Initialize product with a valid payoff definition that transforms price (multiply by 2)
        // We need to set up a controller and other dependencies minimally
        vm.startPrank(address(this));

        // Create a mock controller
        MockController controller = new MockController();
        controller.setCollateral(address(new MockCollateral()));
        controller.setIncentivizer(address(new MockIncentivizer()));
        controller.setOwner(address(this));
        controller.setPauser(address(this));

        // Initialize C with proper product info
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "Test",
            symbol: "TEST",
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType.PASSTHROUGH,
                payoffDirection: PayoffDefinitionLib.PayoffDirection.LONG,
                data: bytes30(uint240(2) | (uint240(1) << 4)) // multiply by 2
            }),
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(1e18),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(1000e18),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(uint128(UFixed18Lib.ONE.unwrap()))
            })
        });

        // We need to set the controller before initialize
        // Since C inherits UControllerProvider which reads controller during initialize,
        // we need to pre-set the controller storage. But we can't use vm.store.
        // Instead, we'll use a patched version that allows setting controller.
        // Since we can't modify C, we rely on the fact that initialize calls __UControllerProvider__initialize
        // which requires msg.sender to be IController. So we need to call from a valid controller.

        // We'll deploy a wrapper that acts as controller for initialization
        address controllerAddr = address(new Deployer());
        Deployer(controllerAddr).deployAndInit(
            address(oracle),
            PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType.PASSTHROUGH,
                payoffDirection: PayoffDefinitionLib.PayoffDirection.LONG,
                data: bytes30(uint240(2) | (uint240(1) << 4))
            })
        );

        vm.stopPrank();

        // Now test atVersion
        uint256 version = 1;
        IOracleProvider.OracleVersion memory result = c.atVersion(version);

        // The transformed price should be oraclePrice * 2
        Fixed18 expectedPrice = Fixed18.wrap(int256(oraclePrice) * 2);
        assertTrue(Fixed18.unwrap(result.price) == Fixed18.unwrap(expectedPrice));
    }
}

