pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";
import {IOracleProvider} from "../src/C_under_test.sol";
import {PayoffDefinition} from "../src/C_under_test.sol";
import {Fixed18} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 oracleVersion, int256 rawPrice) public {
        // Bound rawPrice to avoid arithmetic overflow in Fixed18 operations
        // Fixed18 uses int256, so keep it well within int256 range.
        rawPrice = bound(rawPrice, -1e50, 1e50);
        vm.assume(rawPrice != 0);

        // Deploy a minimal oracle that returns a specific version and price
        MockOracle oracle = new MockOracle(oracleVersion, rawPrice);

        // Use a payoff definition that applies a non-trivial transformation (e.g., scalar multiply)
        // The payoff type and direction are not directly accessible via Solidity constructors,
        // so we construct the raw bytes30 data to represent a simple PayoffDefinition.
        // PayoffType: 0 (PASSTHROUGH) would skip transformation, so we use a different type.
        // PayoffType 1 (SCALAR) with PayoffDirection 0 (LONG) multiplies by a constant.
        // We construct the PayoffDefinition manually:
        // 1 byte payoffType (0x01 = SCALAR)
        // 1 byte payoffDirection (0x00 = LONG)
        // 30 bytes data: left-padded int256 scalar (e.g., 2 * 1e18 as Fixed18)
        bytes memory defBytes = new bytes(32);
        defBytes[0] = bytes1(uint8(1)); // SCALAR
        defBytes[1] = bytes1(uint8(0)); // LONG
        // scalar = 2 * 1e18 = 2000000000000000000
        bytes memory scalarBytes = abi.encodePacked(int256(2 * 1e18));
        for (uint i = 0; i < 30; i++) {
            defBytes[2 + i] = scalarBytes[2 + i];
        }
        PayoffDefinition memory payoffDef;
        assembly {
            payoffDef := mload(add(defBytes, 32))
        }

        C.ProductInfo memory info = C.ProductInfo({
            name: "",
            symbol: "",
            payoffDefinition: payoffDef,
            oracle: oracle,
            maintenance: UFixed18.wrap(1e18),
            fundingFee: UFixed18.wrap(0.1e18),
            makerFee: UFixed18.wrap(0.02e18),
            takerFee: UFixed18.wrap(0.03e18),
            positionFee: UFixed18.wrap(0.001e18),
            makerLimit: UFixed18.wrap(1000e18),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: Fixed18.pack(Fixed18.wrap(0.01e18)),
                maxRate: Fixed18.pack(Fixed18.wrap(1e18)),
                targetRate: Fixed18.pack(Fixed18.wrap(0.5e18)),
                targetUtilization: UFixed18.pack(UFixed18.wrap(0.8e18))
            })
        });

        // We need the controller to be set for initialization. We deploy a minimal controller.
        MockController controller = new MockController();
        vm.prank(address(controller));
        c.initialize(info);

        IOracleProvider.OracleVersion memory result = c.atVersion(oracleVersion);

        Fixed18 transformedPrice = Fixed18.wrap(rawPrice * 2);
        assertEq(Fixed18.unwrap(result.price), Fixed18.unwrap(transformedPrice), "atVersion price must be transformed");
    }
}

contract MockOracle is IOracleProvider {
    uint256 public version;
    int256 public price;

    constructor(uint256 _version, int256 _price) {
        version = _version;
        price = _price;
    }

    function sync() external pure override returns (OracleVersion memory) {
        revert("Not implemented");
    }

    function currentVersion() external view override returns (OracleVersion memory) {
        return OracleVersion({version: version, timestamp: block.timestamp, price: Fixed18.wrap(price)});
    }

    function atVersion(uint256 /* oracleVersion */) external view override returns (OracleVersion memory) {
        return OracleVersion({version: version, timestamp: block.timestamp, price: Fixed18.wrap(price)});
    }
}

